-- ================================================================
-- Azerbaijan (AZ) ES/DE/FR translations, completing 495 (milestones),
-- 497 (deep-dive content) and the Azerbaijan story in 498 against
-- their English content. Written 10 Aug 2026.
--
-- KEYING. milestone_translations and story_translations have natural
-- string PKs, so those are plain INSERT OR IGNORE ... VALUES keyed on
-- the hardcoded ids from 495 and 498. deep_dive_page_translations is
-- keyed on (country_id, lang) via a SELECT against countries.code.
-- The autoincrement deep_dive_stats / cards / steps / portals /
-- lifecycle_cards / lifecycle_statuses_v2 / penalty_rows tables have
-- no natural key, so every row here is looked up via a JOIN on stable
-- identifying columns -- country code + sort_order (stats, steps,
-- penalty rows), country code + section + sort_order (cards,
-- lifecycle cards), country code + url (portals), or via the parent
-- lifecycle card + sort_order (lifecycle statuses). Never via
-- (SELECT MAX(id) ...), which is only safe in the migration that
-- inserts the parent row.
--
-- KEPT UNCHANGED ACROSS LANGUAGES: e-qaimə, AVİS, VÖEN, ASAN İMZA,
-- e-İmza, SİMA Token, ASAN DOC, eFP, İnternet Vergi İdarəsi, e-VHF,
-- elektron vergi hesab-fakturası, Elektron Faktura hazırlama
-- Proqramı, taxes.gov.az / e-taxes.gov.az / nk.gov.az, EN 16931,
-- Peppol, XML, .adoc / .edoc, all article numbers (71-1, 58.13,
-- 58.8.2, 58.13-1, 155.1-1, 218.1.2, 194.2.3, 194.2.8, 71-1.1.3-1,
-- 71-1.1.3-2, 71-1.5.12, 71-1.1.5), decision/decree numbers (89, 26,
-- 563), currency codes, percentages and every emoji. Azerbaijani
-- diacritics (ə, İ, Ö) are preserved exactly.
--
-- LOCALIZED PER HOUSE STYLE (see 186/187 UAE, 401 Costa Rica, 471
-- Bulgaria): the label part of a legal instrument is rendered in the
-- target language while its number is preserved verbatim -- "Cabinet
-- Decision No. 89" -> "Decisión del Gabinete n.º 89" / "Kabinetts-
-- beschluss Nr. 89" / "décision du Cabinet n° 89". Likewise digit
-- grouping follows each language ("AZN 200.000" es/de, "200 000 AZN"
-- fr) and dates follow each language's convention without ever
-- shifting the value. mandate_summary_icon is always '🇦🇿'.
--
-- Terminology follows the site's existing translations: e-invoicing =
-- facturación electrónica / E-Rechnungsstellung / facturation
-- électronique; tax authority = Servicio Tributario Estatal /
-- Staatlicher Steuerdienst / Service national des impôts (the State
-- Tax Service specifically); taxpayer = contribuyente /
-- Steuerpflichtiger / assujetti; input VAT = IVA soportado /
-- Vorsteuerabzug / TVA en amont; "clearance" is kept as clearance.
-- ================================================================

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es',
  'CTC centralizado con registro en el momento de la emisión: el portal del Servicio Tributario Estatal asigna el número de la factura y la registra en AVİS al emitirse, pero no la aprueba en cuanto al fondo — el comprador confirma en un plazo de cinco días, con confirmación automática por silencio',
  'Esta página de análisis en profundidad refleja la normativa azerbaiyana tal y como la publica el Servicio Tributario Estatal (taxes.gov.az) — incluidas su página sobre la e-qaimə, su guía de usuario de 2024, su folleto de sanciones financieras de 2025 y sus preguntas frecuentes sobre las modificaciones de 2026 —, junto con los textos de las decisiones del Gabinete de Ministros publicados en nk.gov.az, con fecha de 10 de agosto de 2026. El Código Tributario consolidado se publica como un único documento de gran tamaño que no pudo recuperarse íntegramente, por lo que nada de lo aquí expuesto cita literalmente el texto legal; cada afirmación se apoya en una publicación oficial del Servicio Tributario Estatal o en una decisión del Gabinete. Se ofrece a título informativo general, no como asesoría legal o tributaria. Confirme los requisitos vigentes con el Servicio Tributario Estatal o con un asesor fiscal azerbaiyano antes de basarse en esta página.',
  'El mandato de la e-qaimə de Azerbaiyán comenzó el 1 de abril de 2017 en virtud de la Decisión del Gabinete n.º 89, que desarrolló el artículo 71-1 del Código Tributario, y se extendió a todos los demás contribuyentes el 1 de enero de 2018. En 2020 se suprimió la factura electrónica de IVA independiente y quedó fusionada en la e-qaimə. La Decisión del Gabinete n.º 26 de 2021 es el reglamento vigente. El 1 de enero de 2026 entraron en vigor nuevas reglas sobre los plazos de emisión.',
  'Una e-qaimə conforme es un documento XML redactado en azerbaiyano, firmado con una firma electrónica avanzada, transmitido al destinatario registrado a través del portal del Servicio Tributario Estatal y registrado en AVİS, el Sistema Automatizado de Información Tributaria. El Servicio Tributario Estatal publica la especificación del formato de archivo, plantillas de ejemplo y un fichero de clasificación de bienes, obras y servicios. La firma se realiza con ASAN İMZA, e-İmza o SİMA Token, y genera contenedores .adoc o .edoc.',
  'El mandato abarca prácticamente a toda la población de suministros comerciales B2B, sin ningún umbral de facturación sobre la propia obligación desde la fase de 2018. El B2C queda fuera de ámbito como regla general — el comercio minorista funciona con cajas registradoras de nueva generación —, aunque un consumidor puede solicitar una factura electrónica en una operación de comercio minorista o de restauración. Quienes no están registrados como contribuyentes no pueden emitir facturas electrónicas en absoluto, y los no residentes no emiten facturas electrónicas azerbaiyanas.',
  'Si suministra bienes, obras o servicios en Azerbaiyán como contribuyente registrado, ya está dentro del ámbito de aplicación, y lo está desde 2018. El trabajo pendiente es el cambio de plazos del 1 de enero de 2026, que resulta genuinamente disruptivo para quien factura servicios continuos con periodicidad trimestral o anual, y que la mayoría de los resúmenes internacionales de cumplimiento aún no ha recogido.',
  'Azerbaiyán publica un régimen sancionador real, cuantificado y escalonado para los incumplimientos en materia de facturación electrónica, y afecta a ambas partes de la operación: al vendedor por no emitir y al comprador por mantener mercancías sin las facturas exigidas.',
  'Azerbaiyán exige facturas electrónicas desde el 1 de abril de 2017, y de forma universal para todos los contribuyentes desde el 1 de enero de 2018, en virtud del artículo 71-1 del Código Tributario y de la Decisión del Gabinete n.º 89. Las facturas son XML, se redactan en azerbaiyano, se firman con una firma electrónica avanzada y se registran en el sistema AVİS del Servicio Tributario Estatal, que asigna la serie y el número; el comprador dispone entonces de cinco días para confirmar, y el silencio equivale a la confirmación. Desde el 1 de enero de 2026, el transporte internacional y los servicios continuos han perdido el plazo general de cinco días para facturar.',
  '🇦🇿'
FROM countries WHERE code = 'AZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 abr. 2017', 'Comienza el mandato de la e-qaimə, en virtud del artículo 71-1 del Código Tributario' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 0;
