INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '55.600', 'Sujetos pasivos de IVA activos a 1 de julio de 2025, un 5,2 % más en seis meses' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'AZN 4.622 M', 'IVA recaudado en 2025 — alrededor del 28 % del total de ingresos tributarios' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '18 %', 'Tipo general del IVA; umbral de registro AZN 200.000' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y firma', '[["Formato de la factura", "XML — el Servicio Tributario Estatal publica la especificación del formato de archivo y plantillas de ejemplo"], ["Idioma", "Azerbaiyano, exigido por la Decisión del Gabinete n.º 26"], ["Firma", "Firma electrónica avanzada, obligatoria tanto en modo en línea como fuera de línea"], ["Mecanismos de firma", "ASAN İMZA (basado en SIM móvil), certificado e-İmza, SİMA Token o el cliente ASAN DOC"], ["Formatos de contenedor", ".adoc y .edoc"], ["Normas europeas", "No sigue EN 16931; Azerbaiyán no es una autoridad Peppol"]]', 'La ausencia de alineación con EN 16931 y con Peppol la afirma una única fuente secundaria y la corrobora el silencio del resto; ninguna fuente primaria se pronuncia en un sentido ni en otro.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'El "modo fuera de línea" no significa lo que parece', NULL, NULL, 'Azerbaiyán ofrece dos modos, y su denominación induce a pensar que uno de ellos permite emitir facturas al margen del sistema estatal. No es así. En el modo en línea, el usuario se autentica en el portal İnternet Vergi İdarəsi con una firma electrónica avanzada y compone y envía la factura en tiempo real. En el modo fuera de línea se descarga eFP — Elektron Faktura hazırlama Proqramı —, se componen y empaquetan las facturas sin conexión a internet, se firma el paquete y después se carga en el portal, momento en el que el Servicio Tributario Estatal asigna la serie y el número y envía la confirmación por correo electrónico. eFP es una herramienta de preparación, no un canal de emisión. No existe ninguna e-qaimə legalmente válida que no pase por el Servicio Tributario Estatal, porque la identidad de la factura — su serie y su número — la asigna el Estado, no el contribuyente.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Ámbito de aplicación, umbrales y plazos', '[["B2B", "Obligatorio y universal — todos los contribuyentes, desde el 1 de enero de 2018"], ["B2G", "Dentro del ámbito; los organismos públicos son destinatarios como cualquier otro contribuyente registrado"], ["B2C", "Fuera de ámbito como regla general — el comercio minorista funciona con cajas registradoras de nueva generación —, pero un consumidor puede solicitar una factura electrónica en una operación de comercio minorista o de restauración"], ["Bienes", "Facturación el mismo día de la entrega"], ["Servicios", "En un plazo de 5 días — salvo las dos excepciones de 2026 que figuran a continuación"], ["Transporte internacional (desde 2026)", "Antes de que comience el transporte"], ["Servicios continuos (desde 2026)", "Mensualmente, al inicio de la prestación de cada mes natural, con independencia del ciclo de facturación"], ["Pagos anticipados", "El día en que se recibe el anticipo"], ["Confirmación del comprador", "5 días para confirmar o devolver para su corrección; el silencio confirma automáticamente"], ["Correcciones", "Hasta el día 20 del mes siguiente al mes declarado"]]', 'El ámbito B2G es una inferencia: lo afirman dos fuentes secundarias y en ningún sitio se excluye, pero ninguna fuente primaria lo menciona expresamente.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'Registro en el momento de la emisión', 'Una e-qaimə recorre esta secuencia tanto en modo en línea como fuera de línea:', 'El Servicio Tributario Estatal está dentro de la operación en tiempo real — pero numera y registra la factura en lugar de aprobarla, y la validación decisiva es la del comprador, o su silencio.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El vendedor redacta la factura en azerbaiyano, en línea en el portal o fuera de línea en eFP' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'La firma con una firma electrónica avanzada y la envía al portal del Servicio Tributario Estatal' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El sistema valida el número de identificación fiscal VÖEN de la contraparte y calcula el IVA automáticamente' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El Servicio Tributario Estatal asigna la serie y el número y registra la factura en AVİS' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El comprador confirma, la devuelve para su corrección o no hace nada — en cuyo caso se confirma automáticamente a los 5 días' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔍 Tres fuentes, tres etiquetas distintas para el mismo sistema', NULL, NULL, 'Quien investigue Azerbaiyán se topará con un problema de nomenclatura, así que conviene decirlo abiertamente. Una fuente de cumplimiento lo califica de modelo de reporte post-auditoría y explícitamente no de preautorización (clearance previo). Otra lo llama "clearance post-auditoría", lo cual es contradictorio en sí mismo. Una tercera lo denomina modelo de clearance. Las tres describen el mismo mecanismo. Esta página no adopta ninguna de esas etiquetas, porque "clearance" exagera lo que ocurre y "post-auditoría" se queda corto. Lo que sí es cierto, según las fuentes primarias: la factura no puede existir fuera del sistema estatal, su identidad la asigna el Estado, queda registrada en AVİS en el momento de la emisión y el sistema valida el número de identificación fiscal de la contraparte y calcula el IVA automáticamente; pero ningún funcionario ni motor de reglas aprueba el contenido de la factura como condición de su validez, y una contraparte pasiva la aprueba automáticamente al cabo de cinco días. Eso es registro en el momento de la emisión, y describirlo en una frase sirve mejor al lector que forzarlo a encajar en una categoría de una sola palabra. Una advertencia más: un artículo del sector de 2025 afirma que Azerbaiyán impuso la facturación electrónica en 2010 en virtud del artículo 2 del Código Tributario. Es falso: el artículo 2 se refiere a la base de la legislación tributaria, y la disposición operativa es el artículo 71-1, introducido con efectos desde el 1 de abril de 2017. Se menciona aquí para que un futuro lector no lo reintroduzca a partir de un resultado de búsqueda.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚠️ Las sanciones se agravan dentro del mismo año natural — y también alcanzan al comprador', NULL, NULL, 'Las cifras de la tabla anterior proceden del propio folleto de 2025 del Servicio Tributario Estatal sobre sanciones financieras. Conviene destacar tres rasgos. Primero, la escalada es por año natural y se reinicia: 10 % para la primera infracción, 20 % para la segunda y 40 % a partir de la tercera. Segundo, el artículo 58.8.2 sanciona al comprador, no al vendedor, cuando se mantienen mercancías sin las facturas exigidas, de modo que ambas partes de una operación asumen riesgo, lo que resulta inusual y convierte el cumplimiento de la contraparte en una cuestión comercial propia y no en un problema ajeno. Tercero, el Servicio Tributario Estatal ha vigilado activamente la frontera entre B2B y B2C: en julio de 2020 advirtió públicamente de que se estaban disfrazando de ventas minoristas en punto de venta operaciones mayoristas que requerían una factura electrónica, registrando importes inverosímilmente elevados en las cajas registradoras, y confirmó que a esa conducta le son aplicables las sanciones del artículo 58.13.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📋 Dos excepciones y una sanción que no existe', NULL, NULL, 'La presentación tardía de una factura electrónica de pago anticipado no conlleva, específicamente, sanción financiera alguna, a diferencia de las facturas electrónicas ordinarias — un elemento diferenciador real y algo llamativo, procedente de portales tributarios profesionales azerbaiyanos y no de la ley. Por otra parte, la presentación de 2017 del Servicio Tributario Estatal canaliza algunas sanciones relacionadas con la factura electrónica a través de los artículos 194.2.3 y 194.2.8, con un 5-10 % por fondos no declarados, en un contexto de impuestos especiales. Y hay algo que conviene decir sin rodeos en lugar de dejarlo implícito: no se ha podido documentar ninguna sanción por la mera emisión tardía de una factura electrónica ordinaria, a diferencia de la falta de emisión. Los artículos sancionadores están redactados en torno al suministro de bienes sin factura electrónica. Esta página no afirma que exista una sanción por emisión tardía, porque no ha podido demostrarse.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔗 Relacionado, pero deliberadamente no mostrado como hito de facturación electrónica', NULL, NULL, 'Desde el 23 de agosto de 2026, los proveedores no residentes de servicios electrónicos a consumidores azerbaiyanos deben registrarse a efectos del IVA y repercutir el 18 % una vez que sus ventas brutas anuales de origen azerbaiyano superen el equivalente en manats de USD 10.000, en sustitución de un régimen de registro voluntario y retención en la fuente. Se trata de una obligación de registro a efectos del IVA, no de una obligación de facturación electrónica — los no residentes no emiten facturas electrónicas azerbaiyanas en absoluto —, por lo que este rastreador no la recoge como hito del mandato. Conviene conocerla por una segunda razón: una alerta de servicios profesionales de abril de 2025 anticipaba este cambio para el 1 de enero de 2026 y sin umbral, señalando que la legislación habilitante aún no se había aprobado. La ley finalmente aprobada trasladó la fecha a agosto de 2026 y añadió el umbral de USD 10.000. Un recordatorio útil de por qué este sitio verifica lo que se ha promulgado y no lo que se esperaba. Por separado, desde el 1 de enero de 2026 un nuevo artículo 155.1-1 aplica un coeficiente de 0,5 a los cobros sin efectivo en punto de venta al comprobar el umbral de registro del IVA, de modo que la facturación con tarjeta computa por la mitad de su valor, lo que significa que un negocio puede realizar unos AZN 400.000 en ventas con tarjeta antes de cruzar la línea de AZN 200.000.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Bienes suministrados sin factura electrónica cuando era obligatoria — 1.ª infracción en el año natural (art. 58.13)', '10 % del valor de la venta, más AZN 100 por cada operación no documentada', 'No se publica ningún límite' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Mismo incumplimiento — 2.ª infracción en el mismo año natural (art. 58.13)', '20 % del valor de la venta, más AZN 100 por cada operación no documentada', 'No se publica ningún límite' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Mismo incumplimiento — 3.ª infracción y siguientes (art. 58.13)', '40 % del valor de la venta, más AZN 100 por cada operación no documentada', 'No se publica ningún límite' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'El comprador mantiene mercancías sin las facturas electrónicas o los documentos de compra exigidos (art. 58.8.2)', '10 % / 20 % / 40 % del valor de las mercancías, con escalada en caso de reiteración dentro del mismo año natural', 'No se publica ningún límite' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Bienes sujetos a impuestos especiales trasladados entre instalaciones del propio contribuyente sin factura electrónica de movimiento interno (art. 58.13-1)', '10 % / 20 % / 40 % del valor de los bienes, más AZN 100 por cada operación no documentada', 'No se publica ningún límite' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Reajuste su ciclo de facturación para los servicios continuos', 'Este es el punto más urgente de la página. Desde el 1 de enero de 2026, los servicios prestados de forma regular y continua — seguridad, limpieza, suministros, suscripciones y la mayoría del SaaS — deben facturarse mensualmente, al inicio del servicio de cada mes, aunque su contrato facture trimestral o anualmente. Si su ERP sigue aplicando una regla general de cinco días para los servicios, está aplicando una regla que ya no está vigente.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Adelante la facturación del transporte al inicio del transporte', 'Los servicios de transporte internacional deben facturarse ahora antes de que comience el transporte, no en los cinco días siguientes. Para los operadores de transporte de mercancías y logística esto invierte el orden habitual de las operaciones y exige un cambio de proceso, no solo un cambio en un campo de fecha.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Obtenga una firma electrónica avanzada y una cuenta en el portal', 'Necesita ASAN İMZA, un certificado e-İmza o un SİMA Token, además de acceso al portal İnternet Vergi İdarəsi. Si tiene previsto preparar facturas de forma masiva fuera de línea, instale también eFP — pero recuerde que prepara, no emite.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Vigile sus facturas recibidas, no solo las emitidas', 'El artículo 58.8.2 sanciona al comprador por mantener mercancías sin las facturas exigidas, con los mismos tipos crecientes del 10/20/40 %. Reclame a los proveedores que no hayan emitido y utilice activamente la ventana de confirmación de cinco días — el silencio equivale a la confirmación, de modo que una factura no revisada se convierte en una factura aceptada.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Vuelva a comprobar su situación de registro a efectos del IVA para 2026', 'El nuevo artículo 155.1-1 computa los cobros sin efectivo en punto de venta por la mitad de su valor al comprobar el umbral de registro de AZN 200.000, de modo que un negocio minorista o de servicios puede alcanzar ahora unos AZN 400.000 de facturación con tarjeta antes de tener que registrarse obligatoriamente. Si estaba cerca del límite, puede que ya no lo esté.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'es', 'Servicio Tributario Estatal — la página oficial sobre la e-qaimə' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'AZ' AND p.url = 'https://www.taxes.gov.az/en/page/elektron-qaime-faktura';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'es', 'İnternet Vergi İdarəsi (cuenta de impuestos electrónicos) — donde se emiten realmente las facturas (requiere inicio de sesión)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'AZ' AND p.url = 'https://www.e-taxes.gov.az';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-e-qaime-2017', 'es',
  'Comienza el mandato de la e-qaimə: contribuyentes registrados a efectos del IVA y del artículo 218.1.2',
  'La Decisión del Gabinete de Ministros n.º 89, de 14 de marzo de 2017, aprobó las reglas sobre la forma, la aplicación, la contabilización y el uso de la factura electrónica, desarrollando el nuevo artículo 71-1 del Código Tributario. Desde el 1 de abril de 2017, las personas registradas a efectos del IVA y las personas comprendidas en el artículo 218.1.2 del Código Tributario -- empresas de comercio y de restauración colectiva cuyas operaciones sujetas superaran los AZN 200.000 en cualquier mes de un periodo móvil de 12 meses -- tuvieron que emitir facturas electrónicas por los bienes entregados, las obras ejecutadas y los servicios prestados en el ejercicio de su actividad. Esta fecha de inicio y este ámbito de aplicación están confirmados en la propia página sobre la e-qaimə del Servicio Tributario Estatal.',
  '["Este es el origen de la obligación actual -- el artículo 71-1 sigue siendo hoy la base legal operativa", "Nota para quien lea comentarios antiguos: son incorrectas las afirmaciones de que Azerbaiyán impuso la facturación electrónica en 2010 en virtud del artículo 2 del Código Tributario"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-universal-2018', 'es',
  'La facturación electrónica se extiende a todos los contribuyentes restantes',
  'Desde el 1 de enero de 2018, la segunda fase del mismo marco del artículo 71-1 incorporó a todos los demás contribuyentes, más allá de los registrados a efectos del IVA y de los del artículo 218.1.2 cubiertos desde abril de 2017. A partir de ese momento, el mandato azerbaiyano abarca prácticamente a toda la población de suministros comerciales B2B, sin ningún umbral de facturación sobre la propia obligación de emitir facturas electrónicas. El escalonamiento figura en la propia presentación sobre la e-qaimə del Servicio Tributario Estatal. Quienes no están registrados como contribuyentes no pueden emitir facturas electrónicas en absoluto.',
  '["Cualquier contribuyente registrado que suministre bienes, obras o servicios en Azerbaiyán está dentro del ámbito de aplicación -- no hay ningún umbral de tamaño por debajo del cual quedar fuera", "La cifra de AZN 200.000 que aparece en los comentarios azerbaiyanos sobre facturación electrónica es un umbral de delimitación de la fase de 2017 y, por separado, un umbral de registro a efectos del IVA; hoy no es un umbral de facturación electrónica"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-single-document-2020', 'es',
  'Se suprime la factura electrónica de IVA; la e-qaimə pasa a ser el único documento principal',
  'Desde el 1 de enero de 2020 se retiró la factura fiscal electrónica (elektron vergi hesab-fakturası, e-VHF) y se fusionó en la e-qaimə, que pasó a ser el documento contable principal de todas las operaciones empresariales. Los sujetos pasivos de IVA utilizan ahora la propia e-qaimə como documento para calcular y deducir el IVA soportado -- antes solo acreditaba el movimiento de las mercancías. Desde esa misma fecha, el emisor ya no puede anular unilateralmente una factura sin el consentimiento del destinatario, y se introdujeron nueve tipos distintos de factura. Conviene decirlo con claridad, porque a menudo se describe mal: esto no fue un paso del papel a lo digital. El documento predecesor azerbaiyano ya era electrónico desde aproximadamente 2008; en 2020 se fusionaron dos sistemas electrónicos en uno solo.',
  '["Si sus sistemas siguen modelando las facturas de IVA y los albaranes de entrega como documentos azerbaiyanos separados, están modelando un régimen que terminó en 2020", "La anulación requiere ahora el acuerdo de la contraparte -- incorpórelo a su proceso de abonos y correcciones"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-advance-invoice-2024', 'es',
  'Las facturas electrónicas por pagos anticipados pasan a ser obligatorias',
  'Desde el 1 de enero de 2024 debe emitirse una factura electrónica el mismo día en que se recibe un pago anticipado, y la posterior factura de entrega debe remitirse a esa factura de anticipo por serie y número. Es de destacar que la obligación no se limita a los sujetos pasivos de IVA -- alcanza también a los contribuyentes del régimen simplificado, a los no sujetos a IVA y a los del impuesto sobre beneficios. De forma inusual, la presentación tardía de una factura electrónica de anticipo no conlleva, específicamente, sanción financiera alguna, a diferencia de las facturas electrónicas ordinarias. Portales tributarios azerbaiyanos secundarios citan esta disposición como el artículo 71-1.5.12, mientras que las propias preguntas frecuentes de 2026 del Servicio Tributario Estatal citan la regla del anticipo como el artículo 71-1.1.5; esa discrepancia de numeración no ha podido conciliarse con un texto consolidado del Código Tributario y aquí se señala en lugar de resolverse.',
  '["Active la factura al recibir el anticipo, no en el momento de la entrega", "Traslade la serie y el número de la factura de anticipo a la factura de entrega", "No dé por supuesto que el criterio es el registro a efectos del IVA -- esta obligación alcanza también a los contribuyentes del régimen simplificado y a los no sujetos a IVA"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-timing-rules-2026', 'es',
  'Se cierra la ventana de cinco días para el transporte internacional y los servicios continuos',
  'Una ley de 9 de diciembre de 2025, aplicada mediante el Decreto Presidencial n.º 563, de 29 de diciembre de 2025, introdujo los artículos 71-1.1.3-1 y 71-1.1.3-2 del Código Tributario con efectos desde el 1 de enero de 2026. El plazo general de cinco días para las facturas de servicios deja de aplicarse a dos categorías. Los servicios de transporte internacional deben facturarse antes de que comience el transporte. Los servicios prestados de forma regular y continua -- seguridad, limpieza, suministros, suscripciones -- deben facturarse por cada mes natural en el momento en que se inicia la prestación de ese mes, incluso cuando el contrato prevea una facturación trimestral o anual. La razón declarada es impedir que los contribuyentes utilicen la ventana de cinco días para desplazar operaciones entre periodos de declaración.',
  '["Si factura a clientes azerbaiyanos con periodicidad trimestral o anual por un servicio continuo, su ciclo de facturación ya no concuerda con la ley -- la factura electrónica es mensual con independencia del ciclo de facturación", "Transporte internacional: la factura debe existir antes de que comience el transporte, no dentro de los cinco días siguientes", "Tenga en cuenta que un resumen sectorial muy citado sigue describiendo una regla general de cinco días; eso dejó de ser correcto a comienzos de 2026"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-azerbaijan-invoice-timing', 'es', 'Azerbaiyán cierra la ventana de cinco días para los servicios continuos y el transporte internacional', 'Azerbaiyán ha cerrado su ventana de cinco días para facturar servicios en dos categorías. Desde el 1 de enero de 2026, el transporte internacional debe facturarse antes de que comience el transporte, y los servicios continuos deben facturarse mensualmente con independencia del ciclo de facturación contractual. Varios resúmenes internacionales de cumplimiento siguen describiendo la regla general de cinco días ya superada.', '<h3>🇦🇿 Azerbaiyán cierra la ventana de cinco días para los servicios continuos y el transporte internacional</h3>
<p>Una ley de 9 de diciembre de 2025, aplicada mediante el Decreto Presidencial n.º 563, de 29 de diciembre de 2025, introdujo dos nuevos artículos en el Código Tributario de Azerbaiyán con efectos desde el 1 de enero de 2026. En conjunto, ponen fin al plazo general de cinco días que regía la facturación de servicios bajo el régimen de la e-qaimə.</p>
<p>Los servicios de transporte internacional deben facturarse ahora antes de que comience el transporte — lo que invierte el orden habitual de las operaciones para los operadores de transporte de mercancías y logística, acostumbrados a facturar a posteriori. Los servicios prestados de forma regular y continua deben facturarse por cada mes natural en el momento en que se inicia la prestación de ese mes, incluso cuando el contrato prevea una facturación trimestral o anual. La propia guía del Servicio Tributario Estatal utiliza un contrato de servicios de seguridad como ejemplo práctico; la misma lógica alcanza a la limpieza, los suministros, las suscripciones y la mayoría de los acuerdos de software como servicio.</p>
<p>La razón declarada es una medida antielusión sencilla: los contribuyentes venían utilizando el periodo de gracia de cinco días para desplazar operaciones a uno u otro lado de los límites de los periodos de declaración.</p>
<p>Lo que hace que esto merezca señalarse es lo discretamente que ha ocurrido. El mandato de Azerbaiyán es universal desde 2018 y está bien asentado, por lo que atrae poca cobertura internacional — y al menos un resumen de cumplimiento muy citado sigue afirmando una regla general de cinco días como si nada hubiera cambiado. Cualquier empresa que facture a un cliente azerbaiyano con periodicidad trimestral o anual por un servicio continuo tiene ahora una cadencia de facturación que no concuerda con la ley, diga lo que diga su contrato.</p>');

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de',
  'Zentralisiertes CTC mit Registrierung bei Ausstellung: Das Portal des Staatlichen Steuerdienstes vergibt die Rechnungsnummer und erfasst die Rechnung bei ihrer Ausstellung in AVİS, genehmigt sie inhaltlich aber nicht — der Käufer bestätigt binnen fünf Tagen, wobei Schweigen als Bestätigung gilt',
  'Diese Analyseseite gibt die aserbaidschanischen Vorschriften so wieder, wie sie der Staatliche Steuerdienst veröffentlicht (taxes.gov.az) — einschließlich seiner e-qaimə-Seite, seines Benutzerhandbuchs von 2024, seiner Broschüre zu Finanzsanktionen von 2025 und seiner FAQ zu den Änderungen 2026 — zusammen mit den auf nk.gov.az veröffentlichten Beschlusstexten des Ministerkabinetts, mit Stand 10. August 2026. Das konsolidierte Steuergesetzbuch wird als ein einziges sehr umfangreiches Dokument bereitgestellt, das nicht vollständig abgerufen werden konnte; nichts auf dieser Seite zitiert daher Gesetzestext wörtlich, jede Aussage stützt sich vielmehr auf eine amtliche Veröffentlichung des Staatlichen Steuerdienstes oder auf einen Kabinettsbeschluss. Die Seite dient der allgemeinen Information und ist keine Rechts- oder Steuerberatung. Bestätigen Sie die geltenden Anforderungen beim Staatlichen Steuerdienst oder bei einem aserbaidschanischen Steuerberater, bevor Sie sich auf diese Seite verlassen.',
  'Aserbaidschans e-qaimə-Mandat begann am 1. April 2017 auf Grundlage des Kabinettsbeschlusses Nr. 89, mit dem Artikel 71-1 des Steuergesetzbuchs umgesetzt wurde, und wurde am 1. Januar 2018 auf alle übrigen Steuerpflichtigen ausgeweitet. 2020 wurde die gesonderte elektronische Mehrwertsteuerrechnung abgeschafft und in die e-qaimə überführt. Der Kabinettsbeschluss Nr. 26 von 2021 ist das derzeit maßgebliche Regelwerk. Zum 1. Januar 2026 traten neue Fristenregelungen in Kraft.',
  'Eine konforme e-qaimə ist ein XML-Dokument, das auf Aserbaidschanisch ausgestellt, mit einer fortgeschrittenen elektronischen Signatur signiert, über das Portal des Staatlichen Steuerdienstes an den registrierten Empfänger übermittelt und in AVİS, dem automatisierten Steuerinformationssystem, erfasst wird. Der Staatliche Steuerdienst veröffentlicht die Dateiformat-Spezifikation, Mustervorlagen und eine Klassifikationsdatei für Waren, Werk- und Dienstleistungen. Signiert wird mit ASAN İMZA, e-İmza oder SİMA Token; dabei entstehen .adoc- oder .edoc-Container.',
  'Das Mandat erfasst praktisch die gesamte B2B-Lieferlandschaft, seit der Phase 2018 ohne Umsatzschwelle für die Pflicht selbst. B2C liegt grundsätzlich außerhalb des Anwendungsbereichs — der Einzelhandel läuft stattdessen über Registrierkassen der neuen Generation —, ein Verbraucher kann jedoch bei einem Einzelhandels- oder Gastronomieumsatz eine elektronische Rechnung verlangen. Personen, die nicht als Steuerpflichtige registriert sind, können überhaupt keine elektronischen Rechnungen ausstellen, und Gebietsfremde stellen keine aserbaidschanischen elektronischen Rechnungen aus.',
  'Wenn Sie als registrierter Steuerpflichtiger in Aserbaidschan Waren, Werk- oder Dienstleistungen liefern, fallen Sie bereits in den Anwendungsbereich, und zwar seit 2018. Die aktuelle Arbeit betrifft die Fristenänderung zum 1. Januar 2026, die für alle, die fortlaufende Dienstleistungen quartalsweise oder jährlich abrechnen, wirklich einschneidend ist und die die meisten internationalen Compliance-Zusammenfassungen noch nicht aufgegriffen haben.',
  'Aserbaidschan veröffentlicht einen echten, bezifferten und ansteigenden Sanktionskatalog für Verstöße gegen die E-Rechnungspflichten, und er trifft beide Seiten des Geschäfts: den Verkäufer für die Nichtausstellung und den Käufer für das Vorhalten von Waren ohne die erforderlichen Rechnungen.',
  'Aserbaidschan verlangt seit dem 1. April 2017 elektronische Rechnungen, seit dem 1. Januar 2018 universell für alle Steuerpflichtigen, auf Grundlage von Artikel 71-1 des Steuergesetzbuchs und des Kabinettsbeschlusses Nr. 89. Rechnungen sind XML-Dokumente, werden auf Aserbaidschanisch ausgestellt, mit einer fortgeschrittenen elektronischen Signatur signiert und im AVİS-System des Staatlichen Steuerdienstes registriert, das Serie und Nummer vergibt; der Käufer hat anschließend fünf Tage Zeit zur Bestätigung, wobei Schweigen als Bestätigung gilt. Seit dem 1. Januar 2026 gilt für internationalen Transport und fortlaufende Dienstleistungen das allgemeine Fünf-Tage-Fenster für die Rechnungsstellung nicht mehr.',
  '🇦🇿'
FROM countries WHERE code = 'AZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Apr. 2017', 'Beginn des e-qaimə-Mandats nach Artikel 71-1 des Steuergesetzbuchs' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '9', 'Unterschiedliche Typen elektronischer Rechnungen in den geltenden Vorschriften' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '55.600', 'Aktive Mehrwertsteuerpflichtige zum 1. Juli 2025, plus 5,2 % in sechs Monaten' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'AZN 4.622 Mio.', 'Im Jahr 2025 vereinnahmte Mehrwertsteuer — rund 28 % des gesamten Steueraufkommens' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '18 %', 'Regelsatz der Mehrwertsteuer; Registrierungsschwelle AZN 200.000' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format und Signatur', '[["Rechnungsformat", "XML — der Staatliche Steuerdienst veröffentlicht die Dateiformat-Spezifikation und Mustervorlagen"], ["Sprache", "Aserbaidschanisch, vorgeschrieben durch Kabinettsbeschluss Nr. 26"], ["Signatur", "Fortgeschrittene elektronische Signatur, im Online- wie im Offline-Modus verpflichtend"], ["Signaturmechanismen", "ASAN İMZA (mobil, SIM-basiert), e-İmza-Zertifikat, SİMA Token oder der ASAN DOC-Client"], ["Containerformate", ".adoc und .edoc"], ["Europäische Standards", "Nicht EN 16931; Aserbaidschan ist keine Peppol-Behörde"]]', 'Das Fehlen einer Ausrichtung an EN 16931 und Peppol wird von einer einzigen Sekundärquelle behauptet und im Übrigen durch Schweigen bestätigt; keine Primärquelle äußert sich dazu in die eine oder andere Richtung.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Der „Offline-Modus" bedeutet nicht das, wonach es klingt', NULL, NULL, 'Aserbaidschan bietet zwei Modi an, und die Bezeichnung verleitet zu der Annahme, einer davon erlaube die Ausstellung von Rechnungen außerhalb des staatlichen Systems. Das ist nicht der Fall. Im Online-Modus authentifiziert man sich mit einer fortgeschrittenen elektronischen Signatur am Portal İnternet Vergi İdarəsi und erstellt und versendet die Rechnung in Echtzeit. Im Offline-Modus lädt man eFP — Elektron Faktura hazırlama Proqramı — herunter, erstellt und verpackt Rechnungen ohne Internetverbindung, signiert das Paket und lädt es anschließend in das Portal hoch; in diesem Moment vergibt der Staatliche Steuerdienst Serie und Nummer und versendet eine Bestätigung per E-Mail. eFP ist ein Vorbereitungswerkzeug, kein Ausstellungskanal. Es gibt keine rechtsgültige e-qaimə, die den Staatlichen Steuerdienst nie berührt, denn die Identität der Rechnung — ihre Serie und ihre Nummer — wird vom Staat und nicht vom Steuerpflichtigen vergeben.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Anwendungsbereich, Schwellenwerte und Fristen', '[["B2B", "Verpflichtend und universell — alle Steuerpflichtigen, seit dem 1. Januar 2018"], ["B2G", "Im Anwendungsbereich; öffentliche Stellen sind Empfänger wie jeder andere registrierte Steuerpflichtige"], ["B2C", "Grundsätzlich außerhalb des Anwendungsbereichs — der Einzelhandel läuft über Registrierkassen der neuen Generation —, ein Verbraucher kann jedoch bei einem Einzelhandels- oder Gastronomieumsatz eine elektronische Rechnung verlangen"], ["Waren", "Rechnung am Tag der Lieferung"], ["Dienstleistungen", "Innerhalb von 5 Tagen — mit Ausnahme der beiden nachstehenden Ausnahmen ab 2026"], ["Internationaler Transport (ab 2026)", "Bevor der Transport beginnt"], ["Fortlaufende Dienstleistungen (ab 2026)", "Monatlich, zu Beginn der Leistungserbringung des jeweiligen Kalendermonats, unabhängig vom Abrechnungszyklus"], ["Vorauszahlungen", "Am Tag des Eingangs der Vorauszahlung"], ["Bestätigung durch den Käufer", "5 Tage zur Bestätigung oder Rücksendung zur Korrektur; Schweigen bestätigt automatisch"], ["Korrekturen", "Bis zum 20. des auf den Meldemonat folgenden Monats"]]', 'Der B2G-Anwendungsbereich ist abgeleitet: Er wird von zwei Sekundärquellen behauptet und nirgends ausgenommen, doch keine Primärquelle benennt ihn ausdrücklich.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Registrierung bei Ausstellung', 'Eine e-qaimə durchläuft diese Abfolge sowohl im Online- als auch im Offline-Modus:', 'Der Staatliche Steuerdienst ist in Echtzeit in die Transaktion eingebunden — er nummeriert und erfasst die Rechnung jedoch, statt sie zu genehmigen, und die entscheidende Validierung ist die des Käufers oder dessen Schweigen.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Der Verkäufer erstellt die Rechnung auf Aserbaidschanisch, online im Portal oder offline in eFP' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Er signiert mit einer fortgeschrittenen elektronischen Signatur und übermittelt sie an das Portal des Staatlichen Steuerdienstes' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Das System prüft die VÖEN-Steuernummer der Gegenpartei und berechnet die Mehrwertsteuer automatisch' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Der Staatliche Steuerdienst vergibt Serie und Nummer und erfasst die Rechnung in AVİS' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Der Käufer bestätigt, sendet zur Korrektur zurück oder tut nichts — in diesem Fall gilt sie nach 5 Tagen als automatisch bestätigt' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔍 Drei Quellen, drei verschiedene Bezeichnungen für dasselbe System', NULL, NULL, 'Wer zu Aserbaidschan recherchiert, stößt auf ein Benennungsproblem, das man offen ansprechen sollte. Eine Compliance-Quelle bezeichnet das System als Post-Audit-Meldemodell und ausdrücklich nicht als Vorabfreigabe (Pre-Clearance). Eine zweite nennt es „Post-Audit-Clearance", was in sich widersprüchlich ist. Eine dritte spricht von einem Clearance-Modell. Alle drei beschreiben denselben Mechanismus. Diese Seite übernimmt keine dieser Bezeichnungen, denn „Clearance" überzeichnet das Geschehen und „Post-Audit" verharmlost es. Tatsächlich zutreffend ist nach den Primärquellen: Die Rechnung kann außerhalb des staatlichen Systems nicht existieren, ihre Identität wird staatlich vergeben, sie wird bei Ausstellung in AVİS erfasst, und das System prüft die Steuernummer der Gegenpartei und berechnet die Mehrwertsteuer automatisch — aber weder ein Steuerbeamter noch eine Regel-Engine genehmigt den Inhalt der Rechnung als Voraussetzung ihrer Gültigkeit, und eine passive Gegenpartei genehmigt sie nach fünf Tagen automatisch. Das ist Registrierung bei Ausstellung, und diese in einem Satz zu beschreiben nützt dem Leser mehr, als sie in eine Ein-Wort-Kategorie zu pressen. Eine weitere Warnung: Ein Branchenartikel von 2025 behauptet, Aserbaidschan habe die E-Rechnungsstellung 2010 nach Artikel 2 des Steuergesetzbuchs vorgeschrieben. Das ist falsch — Artikel 2 betrifft die Grundlagen der Steuergesetzgebung, und die maßgebliche Vorschrift ist Artikel 71-1, eingefügt mit Wirkung zum 1. April 2017. Sie wird hier benannt, damit ein künftiger Leser sie nicht aus einem Suchtreffer wieder aufgreift.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Die Sanktionen steigen innerhalb eines Kalenderjahres — und treffen auch den Käufer', NULL, NULL, 'Die Zahlen in der obigen Tabelle stammen aus der eigenen Broschüre des Staatlichen Steuerdienstes von 2025 zu den Finanzsanktionen. Drei Merkmale sind hervorzuheben. Erstens erfolgt die Steigerung je Kalenderjahr und wird zurückgesetzt: 10 % beim ersten Verstoß, 20 % beim zweiten, 40 % ab dem dritten. Zweitens belastet Artikel 58.8.2 den Käufer und nicht den Verkäufer, wenn Waren ohne die erforderlichen Rechnungen vorgehalten werden — beide Seiten eines Geschäfts tragen also ein Risiko, was ungewöhnlich ist und die Compliance der Gegenpartei zu einem eigenen kaufmännischen Anliegen macht statt zum Problem eines anderen. Drittens hat der Staatliche Steuerdienst die Grenze zwischen B2B und B2C aktiv überwacht: Im Juli 2020 warnte er öffentlich davor, dass Großhandelsumsätze, für die eine elektronische Rechnung erforderlich ist, als Einzelhandelsverkäufe am Point of Sale getarnt wurden, indem unplausibel hohe Beträge über Registrierkassen gebucht wurden, und bestätigte, dass für dieses Verhalten die Sanktionen nach Artikel 58.13 gelten.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📋 Zwei Ausnahmen und eine Sanktion, die es nicht gibt', NULL, NULL, 'Die verspätete Einreichung einer elektronischen Vorauszahlungsrechnung zieht — anders als bei gewöhnlichen elektronischen Rechnungen — ausdrücklich keine Finanzsanktion nach sich: ein echtes und etwas eigenwilliges Unterscheidungsmerkmal, das auf aserbaidschanische Fachportale zum Steuerrecht und nicht auf das Gesetz zurückgeht. Daneben ordnet die Präsentation des Staatlichen Steuerdienstes von 2017 einige rechnungsbezogene Sanktionen den Artikeln 194.2.3 und 194.2.8 mit 5-10 % für nicht offengelegte Mittel zu, und zwar im Verbrauchsteuerkontext. Und eines sollte man deutlich sagen, statt es nur anzudeuten: Für die bloß verspätete Ausstellung einer gewöhnlichen elektronischen Rechnung — im Unterschied zur Nichtausstellung — ließ sich keine Sanktion belegen. Die Sanktionsvorschriften sind auf die Lieferung von Waren ohne elektronische Rechnung zugeschnitten. Diese Seite behauptet nicht, dass eine Sanktion für verspätete Ausstellung besteht, weil sich das nicht nachweisen ließ.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔗 Verwandt, aber bewusst nicht als E-Invoicing-Meilenstein dargestellt', NULL, NULL, 'Ab dem 23. August 2026 müssen gebietsfremde Anbieter elektronischer Dienstleistungen an aserbaidschanische Verbraucher sich für Mehrwertsteuerzwecke registrieren und 18 % berechnen, sobald ihre jährlichen Bruttoumsätze aus aserbaidschanischen Quellen den Manat-Gegenwert von USD 10.000 übersteigen; damit wird eine Regelung aus freiwilliger Registrierung und Quellenabzug abgelöst. Dies ist eine Pflicht zur Mehrwertsteuerregistrierung und keine E-Invoicing-Pflicht — Gebietsfremde stellen überhaupt keine aserbaidschanischen elektronischen Rechnungen aus —, weshalb dieser Tracker sie nicht als Mandats-Meilenstein führt. Aus einem zweiten Grund lohnt es sich, davon zu wissen: Ein Mandantenhinweis einer Beratungsgesellschaft vom April 2025 prognostizierte diese Änderung für den 1. Januar 2026 und ohne Schwellenwert und merkte an, das Ermächtigungsgesetz sei noch nicht verabschiedet. Das tatsächlich verabschiedete Gesetz verschob den Termin auf August 2026 und ergänzte den Schwellenwert von USD 10.000. Eine nützliche Erinnerung daran, warum diese Website gegen das Verabschiedete und nicht gegen das Erwartete prüft. Davon unabhängig wendet ein neuer Artikel 155.1-1 seit dem 1. Januar 2026 bei der Prüfung der Mehrwertsteuer-Registrierungsschwelle einen Koeffizienten von 0,5 auf bargeldlose Point-of-Sale-Einnahmen an, sodass Kartenumsätze nur zur Hälfte zählen — ein Unternehmen kann also rund AZN 400.000 an Kartenumsatz erzielen, bevor es die Grenze von AZN 200.000 überschreitet.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Waren ohne die erforderliche elektronische Rechnung geliefert — 1. Verstoß im Kalenderjahr (Art. 58.13)', '10 % des Verkaufswerts, zuzüglich AZN 100 je nicht dokumentierter Transaktion', 'Keine Obergrenze veröffentlicht' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Derselbe Verstoß — 2. Verstoß im selben Kalenderjahr (Art. 58.13)', '20 % des Verkaufswerts, zuzüglich AZN 100 je nicht dokumentierter Transaktion', 'Keine Obergrenze veröffentlicht' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Derselbe Verstoß — 3. und weitere Verstöße (Art. 58.13)', '40 % des Verkaufswerts, zuzüglich AZN 100 je nicht dokumentierter Transaktion', 'Keine Obergrenze veröffentlicht' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Der Käufer hält Waren ohne die erforderlichen elektronischen Rechnungen oder Einkaufsbelege vor (Art. 58.8.2)', '10 % / 20 % / 40 % des Warenwerts, ansteigend bei Wiederholung innerhalb eines Kalenderjahres', 'Keine Obergrenze veröffentlicht' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Verbrauchsteuerpflichtige Waren ohne elektronische Rechnung für die interne Verbringung zwischen eigenen Betriebsstätten des Steuerpflichtigen befördert (Art. 58.13-1)', '10 % / 20 % / 40 % des Warenwerts, zuzüglich AZN 100 je nicht dokumentierter Transaktion', 'Keine Obergrenze veröffentlicht' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Passen Sie Ihren Rechnungszyklus für fortlaufende Dienstleistungen an', 'Das ist der dringendste Punkt auf dieser Seite. Seit dem 1. Januar 2026 müssen regelmäßig und fortlaufend erbrachte Dienstleistungen — Sicherheit, Reinigung, Versorgungsleistungen, Abonnements und die meisten SaaS-Angebote — monatlich abgerechnet werden, jeweils zu Beginn der Leistung des betreffenden Monats, selbst wenn Ihr Vertrag quartalsweise oder jährlich abrechnet. Wenn Ihr ERP noch einer pauschalen Fünf-Tage-Regel für Dienstleistungen folgt, folgt es einer Regel, die nicht mehr gilt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Ziehen Sie die Transportfakturierung vor den Transport', 'Internationale Transportdienstleistungen müssen nun bis zum Beginn des Transports abgerechnet werden, nicht innerhalb von fünf Tagen danach. Für Fracht- und Logistikunternehmen kehrt das die übliche Reihenfolge um und erfordert eine Prozessänderung, nicht nur ein anderes Datumsfeld.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Besorgen Sie sich eine fortgeschrittene elektronische Signatur und ein Portalkonto', 'Sie benötigen ASAN İMZA, ein e-İmza-Zertifikat oder ein SİMA Token sowie Zugang zum Portal İnternet Vergi İdarəsi. Wenn Sie Rechnungen in großer Zahl offline vorbereiten wollen, installieren Sie zusätzlich eFP — denken Sie aber daran, dass es Rechnungen vorbereitet und nicht ausstellt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Behalten Sie Ihre Eingangsrechnungen im Blick, nicht nur die Ausgangsrechnungen', 'Artikel 58.8.2 sanktioniert den Käufer, wenn er Waren ohne die erforderlichen Rechnungen vorhält, mit denselben ansteigenden Sätzen von 10/20/40 %. Haken Sie bei Lieferanten nach, die nicht ausgestellt haben, und nutzen Sie das fünftägige Bestätigungsfenster aktiv — Schweigen gilt als Bestätigung, sodass eine ungeprüfte Rechnung zu einer akzeptierten wird.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Überprüfen Sie Ihre Mehrwertsteuer-Registrierungssituation für 2026 erneut', 'Der neue Artikel 155.1-1 zählt bargeldlose Point-of-Sale-Einnahmen bei der Prüfung der Registrierungsschwelle von AZN 200.000 nur zur Hälfte, sodass ein Einzelhandels- oder Dienstleistungsunternehmen nun rund AZN 400.000 Kartenumsatz erzielen kann, bevor eine Registrierungspflicht entsteht. Wer nahe an der Grenze lag, ist es womöglich nicht mehr.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'Staatlicher Steuerdienst — die offizielle e-qaimə-Seite' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'AZ' AND p.url = 'https://www.taxes.gov.az/en/page/elektron-qaime-faktura';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'İnternet Vergi İdarəsi (elektronisches Steuerkonto) — hier werden Rechnungen tatsächlich ausgestellt (Anmeldung erforderlich)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'AZ' AND p.url = 'https://www.e-taxes.gov.az';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-e-qaime-2017', 'de',
  'Das e-qaimə-Mandat beginnt: mehrwertsteuerlich registrierte Steuerpflichtige und Steuerpflichtige nach Artikel 218.1.2',
  'Der Beschluss des Ministerkabinetts Nr. 89 vom 14. März 2017 billigte die Regeln zu Form, Anwendung, Verbuchung und Verwendung der elektronischen Rechnung und setzte damit den neuen Artikel 71-1 des Steuergesetzbuchs um. Ab dem 1. April 2017 mussten mehrwertsteuerlich registrierte Personen sowie Personen im Sinne von Artikel 218.1.2 des Steuergesetzbuchs -- Handels- und Gastronomiebetriebe, deren steuerpflichtige Umsätze in einem beliebigen Monat eines rollierenden Zwölfmonatszeitraums AZN 200.000 überstiegen -- elektronische Rechnungen für gelieferte Waren, erbrachte Werkleistungen und erbrachte Dienstleistungen im Rahmen ihrer Geschäftstätigkeit ausstellen. Startdatum und Anwendungsbereich sind auf der eigenen e-qaimə-Seite des Staatlichen Steuerdienstes bestätigt.',
  '["Dies ist der Ursprung der heutigen Verpflichtung -- Artikel 71-1 ist bis heute die maßgebliche Rechtsgrundlage", "Hinweis für alle, die ältere Kommentare lesen: Behauptungen, Aserbaidschan habe die E-Rechnungsstellung 2010 nach Artikel 2 des Steuergesetzbuchs vorgeschrieben, sind falsch"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-universal-2018', 'de',
  'Die E-Rechnungsstellung wird auf alle übrigen Steuerpflichtigen ausgeweitet',
  'Ab dem 1. Januar 2018 erfasste die zweite Phase desselben Rahmens nach Artikel 71-1 alle übrigen Steuerpflichtigen, über die seit April 2017 einbezogenen mehrwertsteuerlich registrierten Personen und die Personen nach Artikel 218.1.2 hinaus. Von diesem Zeitpunkt an deckt das aserbaidschanische Mandat praktisch die gesamte B2B-Lieferlandschaft ab, ohne Umsatzschwelle für die E-Rechnungspflicht selbst. Die Stufenfolge ist in der eigenen e-qaimə-Präsentation des Staatlichen Steuerdienstes dargestellt. Personen, die nicht als Steuerpflichtige registriert sind, können überhaupt keine elektronischen Rechnungen ausstellen.',
  '["Jeder registrierte Steuerpflichtige, der in Aserbaidschan Waren, Werk- oder Dienstleistungen liefert, fällt in den Anwendungsbereich -- es gibt keine Größenschwelle, unterhalb derer man herausfällt", "Die Zahl von AZN 200.000, die in aserbaidschanischen Kommentaren zur E-Rechnungsstellung auftaucht, ist eine Abgrenzungsschwelle der Phase 2017 sowie -- davon getrennt -- eine Schwelle für die Mehrwertsteuerregistrierung; sie ist heute keine E-Rechnungsschwelle"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-single-document-2020', 'de',
  'Die elektronische Mehrwertsteuerrechnung wird abgeschafft; die e-qaimə wird zum einzigen Primärdokument',
  'Zum 1. Januar 2020 wurde die elektronische Steuerrechnung (elektron vergi hesab-fakturası, e-VHF) abgeschafft und in die e-qaimə überführt, die damit zum primären Buchungsbeleg für sämtliche Geschäftsvorfälle wurde. Mehrwertsteuerpflichtige nutzen nun die e-qaimə selbst als Beleg für die Berechnung und den Vorsteuerabzug -- zuvor belegte sie lediglich die Warenbewegung. Ab demselben Datum kann ein Aussteller eine Rechnung nicht mehr einseitig ohne Zustimmung des Empfängers stornieren, und es wurden neun unterschiedliche Rechnungstypen eingeführt. Das sollte man klar sagen, weil es oft falsch dargestellt wird: Dies war kein Schritt von Papier zu digital. Aserbaidschans Vorgängerdokument war bereits seit etwa 2008 elektronisch; 2020 wurden zwei elektronische Systeme zu einem zusammengeführt.',
  '["Wenn Ihre Systeme Mehrwertsteuerrechnungen und Lieferscheine noch als getrennte aserbaidschanische Dokumente abbilden, bilden sie ein Regime ab, das 2020 geendet hat", "Eine Stornierung erfordert nun die Zustimmung der Gegenpartei -- bauen Sie das in Ihren Gutschrift- und Korrekturprozess ein"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-advance-invoice-2024', 'de',
  'Elektronische Rechnungen für Vorauszahlungen werden verpflichtend',
  'Ab dem 1. Januar 2024 muss an dem Tag, an dem eine Vorauszahlung eingeht, eine elektronische Rechnung ausgestellt werden, und die spätere Lieferrechnung muss mit Serie und Nummer auf diese Vorauszahlungsrechnung verweisen. Bemerkenswert ist, dass die Pflicht nicht auf Mehrwertsteuerpflichtige beschränkt ist -- erfasst sind auch Steuerpflichtige der vereinfachten Besteuerung, nicht mehrwertsteuerpflichtige Personen und Gewinnsteuerpflichtige. Ungewöhnlicherweise zieht die verspätete Einreichung einer Vorauszahlungsrechnung ausdrücklich keine Finanzsanktion nach sich, anders als bei gewöhnlichen elektronischen Rechnungen. Sekundäre aserbaidschanische Steuerportale führen diese Bestimmung als Artikel 71-1.5.12 an, während die eigene FAQ des Staatlichen Steuerdienstes für 2026 die Vorauszahlungsregel als Artikel 71-1.1.5 zitiert; diese Abweichung in der Nummerierung ließ sich nicht gegen einen konsolidierten Text des Steuergesetzbuchs auflösen und wird hier gekennzeichnet statt aufgelöst.',
  '["Lösen Sie die Rechnung beim Eingang der Vorauszahlung aus, nicht bei der Lieferung", "Führen Sie Serie und Nummer der Vorauszahlungsrechnung in der Lieferrechnung fort", "Gehen Sie nicht davon aus, dass die Mehrwertsteuerregistrierung das Kriterium ist -- diese Pflicht trifft auch Steuerpflichtige der vereinfachten Besteuerung und nicht mehrwertsteuerpflichtige Personen"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-timing-rules-2026', 'de',
  'Das Fünf-Tage-Fenster für Dienstleistungen entfällt für internationalen Transport und fortlaufende Dienstleistungen',
  'Ein Gesetz vom 9. Dezember 2025, angewandt durch das Präsidialdekret Nr. 563 vom 29. Dezember 2025, fügte mit Wirkung zum 1. Januar 2026 die Artikel 71-1.1.3-1 und 71-1.1.3-2 in das Steuergesetzbuch ein. Die allgemeine Fünf-Tage-Frist für Dienstleistungsrechnungen gilt für zwei Kategorien nicht mehr. Internationale Transportdienstleistungen müssen bis zum Beginn des Transports abgerechnet werden. Regelmäßig und fortlaufend erbrachte Dienstleistungen -- Sicherheit, Reinigung, Versorgungsleistungen, Abonnements -- müssen für jeden Kalendermonat zu dem Zeitpunkt abgerechnet werden, zu dem die Leistungserbringung dieses Monats beginnt, selbst wenn der Vertrag eine quartalsweise oder jährliche Abrechnung vorsieht. Als Begründung wird angeführt, dass Steuerpflichtige das Fünf-Tage-Fenster nicht länger nutzen sollen, um Umsätze zwischen Meldezeiträumen zu verschieben.',
  '["Wenn Sie aserbaidschanischen Kunden eine fortlaufende Dienstleistung quartalsweise oder jährlich in Rechnung stellen, passt Ihr Rechnungszyklus nicht mehr zum Gesetz -- die elektronische Rechnung ist unabhängig vom Abrechnungszyklus monatlich", "Internationaler Transport: Die Rechnung muss vor Beginn des Transports vorliegen, nicht innerhalb von fünf Tagen danach", "Beachten Sie, dass eine viel zitierte Branchenzusammenfassung weiterhin eine pauschale Fünf-Tage-Regel beschreibt; das ist seit Anfang 2026 nicht mehr zutreffend"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-azerbaijan-invoice-timing', 'de', 'Aserbaidschan schließt das Fünf-Tage-Fenster für fortlaufende Dienstleistungen und internationalen Transport', 'Aserbaidschan hat sein Fünf-Tage-Fenster für die Abrechnung von Dienstleistungen für zwei Kategorien geschlossen. Seit dem 1. Januar 2026 muss internationaler Transport vor Beginn des Transports abgerechnet werden, und fortlaufende Dienstleistungen müssen monatlich abgerechnet werden, unabhängig vom vertraglichen Abrechnungszyklus. Mehrere internationale Compliance-Zusammenfassungen beschreiben nach wie vor die überholte pauschale Fünf-Tage-Regel.', '<h3>🇦🇿 Aserbaidschan schließt das Fünf-Tage-Fenster für fortlaufende Dienstleistungen und internationalen Transport</h3>
<p>Ein Gesetz vom 9. Dezember 2025, angewandt durch das Präsidialdekret Nr. 563 vom 29. Dezember 2025, fügte mit Wirkung zum 1. Januar 2026 zwei neue Artikel in das aserbaidschanische Steuergesetzbuch ein. Zusammen beenden sie die pauschale Fünf-Tage-Frist, die die Abrechnung von Dienstleistungen im e-qaimə-Regime bislang bestimmt hat.</p>
<p>Internationale Transportdienstleistungen müssen nun bis zum Beginn des Transports abgerechnet werden — was die übliche Reihenfolge für Fracht- und Logistikunternehmen umkehrt, die gewohnt sind, im Nachhinein abzurechnen. Regelmäßig und fortlaufend erbrachte Dienstleistungen müssen für jeden Kalendermonat zu dem Zeitpunkt abgerechnet werden, zu dem die Leistungserbringung dieses Monats beginnt, selbst wenn der Vertrag eine quartalsweise oder jährliche Abrechnung vorsieht. Der Leitfaden des Staatlichen Steuerdienstes verwendet einen Vertrag über Sicherheitsdienstleistungen als durchgerechnetes Beispiel; dieselbe Logik erfasst Reinigung, Versorgungsleistungen, Abonnements und die meisten Software-as-a-Service-Vereinbarungen.</p>
<p>Als Begründung wird eine schlichte Missbrauchsabwehr genannt: Steuerpflichtige hatten die fünftägige Schonfrist genutzt, um Umsätze über die Grenzen von Meldezeiträumen hinweg zu verschieben.</p>
<p>Bemerkenswert ist vor allem, wie leise diese Änderung eingeschlagen ist. Aserbaidschans Mandat gilt seit 2018 universell und ist gut etabliert, weshalb es international kaum Beachtung findet — und mindestens eine viel zitierte Compliance-Zusammenfassung nennt weiterhin eine pauschale Fünf-Tage-Regel, als hätte sich nichts geändert. Jedes Unternehmen, das einem aserbaidschanischen Kunden eine fortlaufende Dienstleistung quartalsweise oder jährlich in Rechnung stellt, hat nun einen Rechnungsrhythmus, der nicht mehr zum Gesetz passt, was auch immer im Vertrag steht.</p>');

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'CTC centralisé avec enregistrement au moment de l''émission : le portail du Service national des impôts attribue le numéro de la facture et enregistre celle-ci dans AVİS dès son émission, mais ne l''approuve pas sur le fond — l''acheteur confirme dans un délai de cinq jours, le silence valant confirmation automatique',
  'Cette page d''analyse approfondie reflète les règles azerbaïdjanaises telles que publiées par le Service national des impôts (taxes.gov.az) — y compris sa page consacrée à l''e-qaimə, son guide utilisateur de 2024, sa brochure de 2025 sur les sanctions financières et sa FAQ sur les modifications de 2026 — ainsi que les textes des décisions du Cabinet des ministres publiés sur nk.gov.az, à la date du 10 août 2026. Le Code fiscal consolidé est diffusé sous la forme d''un document unique très volumineux qui n''a pas pu être récupéré intégralement : rien ici ne cite donc le texte légal mot pour mot, chaque affirmation reposant sur une publication officielle du Service national des impôts ou sur une décision du Cabinet. Fourni à titre d''information générale, et non comme un conseil juridique ou fiscal. Confirmez les exigences en vigueur auprès du Service national des impôts ou d''un conseiller fiscal azerbaïdjanais avant de vous fier à cette page.',
  'Le mandat e-qaimə de l''Azerbaïdjan a débuté le 1er avril 2017 en vertu de la décision du Cabinet n° 89, qui met en œuvre l''article 71-1 du Code fiscal, et a été étendu à tous les autres assujettis le 1er janvier 2018. En 2020, la facture électronique de TVA distincte a été supprimée et fusionnée dans l''e-qaimə. La décision du Cabinet n° 26 de 2021 constitue le règlement en vigueur. De nouvelles règles de délais sont entrées en application le 1er janvier 2026.',
  'Une e-qaimə conforme est un document XML rédigé en azerbaïdjanais, signé au moyen d''une signature électronique avancée, transmis au destinataire immatriculé via le portail du Service national des impôts et enregistré dans AVİS, le système automatisé d''information fiscale. Le Service national des impôts publie la spécification du format de fichier, des modèles types et un fichier de classification des biens, travaux et services. La signature s''effectue avec ASAN İMZA, e-İmza ou SİMA Token et produit des conteneurs .adoc ou .edoc.',
  'Le mandat couvre pratiquement l''ensemble des livraisons commerciales B2B, sans aucun seuil de chiffre d''affaires attaché à l''obligation elle-même depuis la phase de 2018. Le B2C est en principe hors périmètre — le commerce de détail fonctionne avec des caisses enregistreuses de nouvelle génération — même si un consommateur peut demander une facture électronique lors d''une opération de détail ou de restauration. Les personnes qui ne sont pas immatriculées en tant qu''assujetties ne peuvent pas du tout émettre de factures électroniques, et les non-résidents n''émettent pas de factures électroniques azerbaïdjanaises.',
  'Si vous fournissez des biens, des travaux ou des services en Azerbaïdjan en tant qu''assujetti immatriculé, vous êtes déjà dans le périmètre, et ce depuis 2018. Le chantier du moment est le changement de délais du 1er janvier 2026, réellement perturbant pour quiconque facture des services continus selon un cycle trimestriel ou annuel, et que la plupart des synthèses internationales de conformité n''ont pas encore intégré.',
  'L''Azerbaïdjan publie un barème de sanctions réel, chiffré et progressif pour les manquements en matière de facturation électronique, et celui-ci frappe les deux côtés de l''opération : le vendeur qui n''émet pas, et l''acheteur qui détient des marchandises sans les factures requises.',
  'L''Azerbaïdjan impose les factures électroniques depuis le 1er avril 2017, de manière universelle pour tous les assujettis depuis le 1er janvier 2018, en vertu de l''article 71-1 du Code fiscal et de la décision du Cabinet n° 89. Les factures sont en XML, rédigées en azerbaïdjanais, signées au moyen d''une signature électronique avancée et enregistrées dans le système AVİS du Service national des impôts, qui attribue la série et le numéro ; l''acheteur dispose ensuite de cinq jours pour confirmer, le silence valant confirmation. Depuis le 1er janvier 2026, le transport international et les services continus ont perdu le bénéfice du délai général de cinq jours pour facturer.',
  '🇦🇿'
FROM countries WHERE code = 'AZ';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er avr. 2017', 'Début du mandat e-qaimə, en vertu de l''article 71-1 du Code fiscal' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '9', 'Types distincts de facture électronique définis par les règles en vigueur' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '55 600', 'Assujettis à la TVA actifs au 1er juillet 2025, en hausse de 5,2 % sur six mois' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '4 622 M AZN', 'TVA collectée en 2025 — environ 28 % des recettes fiscales totales' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '18 %', 'Taux normal de TVA ; seuil d''immatriculation de 200 000 AZN' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'AZ' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et signature', '[["Format de la facture", "XML — le Service national des impôts publie la spécification du format de fichier et des modèles types"], ["Langue", "Azerbaïdjanais, imposé par la décision du Cabinet n° 26"], ["Signature", "Signature électronique avancée, obligatoire en mode en ligne comme hors ligne"], ["Mécanismes de signature", "ASAN İMZA (sur SIM mobile), certificat e-İmza, SİMA Token ou le client ASAN DOC"], ["Formats de conteneur", ".adoc et .edoc"], ["Normes européennes", "Pas EN 16931 ; l''Azerbaïdjan n''est pas une autorité Peppol"]]', 'L''absence d''alignement sur EN 16931 et sur Peppol est affirmée par une seule source secondaire et corroborée par le silence des autres ; aucune source primaire ne se prononce dans un sens ou dans l''autre.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Le « mode hors ligne » ne veut pas dire ce qu''il semble dire', NULL, NULL, 'L''Azerbaïdjan propose deux modes, et leur appellation laisse croire à tort que l''un d''eux permettrait d''émettre des factures en dehors du système étatique. Il n''en est rien. En mode en ligne, on s''authentifie sur le portail İnternet Vergi İdarəsi au moyen d''une signature électronique avancée, puis on rédige et envoie la facture en temps réel. En mode hors ligne, on télécharge eFP — Elektron Faktura hazırlama Proqramı —, on rédige et regroupe les factures sans connexion internet, on signe le lot, puis on le téléverse sur le portail : c''est à ce moment que le Service national des impôts attribue la série et le numéro et envoie une confirmation par courriel. eFP est un outil de préparation, pas un canal d''émission. Il n''existe aucune e-qaimə juridiquement valable qui ne passe jamais par le Service national des impôts, car l''identité de la facture — sa série et son numéro — est attribuée par l''État et non par l''assujetti.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Périmètre, seuils et délais', '[["B2B", "Obligatoire et universel — tous les assujettis, depuis le 1er janvier 2018"], ["B2G", "Dans le périmètre ; les organismes publics sont destinataires comme tout autre assujetti immatriculé"], ["B2C", "Hors périmètre en principe — le commerce de détail fonctionne avec des caisses enregistreuses de nouvelle génération —, mais un consommateur peut demander une facture électronique lors d''une opération de détail ou de restauration"], ["Biens", "Facturation le jour même de la livraison"], ["Services", "Dans un délai de 5 jours — sauf les deux exceptions de 2026 ci-dessous"], ["Transport international (à partir de 2026)", "Avant le début du transport"], ["Services continus (à partir de 2026)", "Mensuellement, au début de la prestation de chaque mois civil, quel que soit le cycle de facturation"], ["Acomptes", "Le jour de la réception de l''acompte"], ["Confirmation par l''acheteur", "5 jours pour confirmer ou renvoyer pour correction ; le silence vaut confirmation automatique"], ["Corrections", "Jusqu''au 20 du mois suivant le mois déclaré"]]', 'Le périmètre B2G est déduit : il est affirmé par deux sources secondaires et n''est exclu nulle part, mais aucune source primaire ne le mentionne explicitement.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Enregistrement au moment de l''émission', 'Une e-qaimə suit cette séquence, en mode en ligne comme en mode hors ligne :', 'Le Service national des impôts est présent dans la transaction en temps réel — mais il numérote et enregistre la facture au lieu de l''approuver, et la validation décisive est celle de l''acheteur, ou son silence.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Le vendeur rédige la facture en azerbaïdjanais, en ligne sur le portail ou hors ligne dans eFP' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Il la signe avec une signature électronique avancée et la transmet au portail du Service national des impôts' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Le système valide le numéro d''identification fiscale VÖEN de la contrepartie et calcule automatiquement la TVA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Le Service national des impôts attribue la série et le numéro et enregistre la facture dans AVİS' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'L''acheteur confirme, renvoie pour correction ou ne fait rien — auquel cas la facture est automatiquement confirmée au bout de 5 jours' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'AZ' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔍 Trois sources, trois étiquettes différentes pour le même système', NULL, NULL, 'Quiconque se documente sur l''Azerbaïdjan se heurtera à un problème de dénomination, autant le dire franchement. Une source de conformité qualifie ce système de modèle de déclaration post-audit et explicitement pas de préautorisation (clearance préalable). Une deuxième parle de « clearance post-audit », ce qui est contradictoire en soi. Une troisième évoque un modèle de clearance. Toutes trois décrivent le même mécanisme. Cette page ne retient aucune de ces étiquettes, car « clearance » surestime ce qui se passe et « post-audit » le sous-estime. Ce qui est effectivement vrai, d''après les sources primaires : la facture ne peut pas exister en dehors du système étatique, son identité est attribuée par l''État, elle est enregistrée dans AVİS au moment de son émission, et le système valide le numéro d''identification fiscale de la contrepartie et calcule automatiquement la TVA — mais aucun agent des impôts ni moteur de règles n''approuve le fond de la facture comme condition de sa validité, et une contrepartie passive l''approuve automatiquement au bout de cinq jours. Il s''agit d''un enregistrement au moment de l''émission, et le décrire en une phrase sert mieux le lecteur que de le faire entrer de force dans une catégorie d''un seul mot. Autre mise en garde : un article sectoriel de 2025 affirme que l''Azerbaïdjan a rendu la facturation électronique obligatoire en 2010 en vertu de l''article 2 du Code fiscal. C''est faux — l''article 2 porte sur le fondement de la législation fiscale, et la disposition applicable est l''article 71-1, inséré avec effet au 1er avril 2017. Il est nommé ici afin qu''un futur lecteur ne le réintroduise pas à partir d''un résultat de recherche.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ Les sanctions s''aggravent au cours d''une même année civile — et touchent aussi l''acheteur', NULL, NULL, 'Les chiffres du tableau ci-dessus proviennent de la propre brochure 2025 du Service national des impôts sur les sanctions financières. Trois caractéristiques méritent d''être soulignées. Premièrement, l''aggravation s''apprécie par année civile et se réinitialise : 10 % pour la première infraction, 20 % pour la deuxième, 40 % à partir de la troisième. Deuxièmement, l''article 58.8.2 sanctionne l''acheteur, et non le vendeur, lorsque des marchandises sont détenues sans les factures requises — les deux parties à une opération sont donc exposées, ce qui est inhabituel et fait de la conformité de la contrepartie une préoccupation commerciale propre plutôt que le problème d''un autre. Troisièmement, le Service national des impôts a activement surveillé la frontière entre B2B et B2C : en juillet 2020, il a publiquement averti que des opérations de gros nécessitant une facture électronique étaient déguisées en ventes de détail au point de vente, en passant des montants invraisemblablement élevés par les caisses enregistreuses, et il a confirmé que les sanctions de l''article 58.13 s''appliquent à ce comportement.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📋 Deux exceptions, et une sanction qui n''existe pas', NULL, NULL, 'Le dépôt tardif d''une facture électronique d''acompte n''entraîne précisément aucune sanction financière, contrairement aux factures électroniques ordinaires — une différence réelle et un peu curieuse, issue de portails fiscaux professionnels azerbaïdjanais plutôt que de la loi. Par ailleurs, la présentation de 2017 du Service national des impôts rattache certaines sanctions liées aux factures électroniques aux articles 194.2.3 et 194.2.8, à hauteur de 5-10 % pour des fonds non déclarés, dans un contexte d''accises. Et il y a une chose qu''il vaut mieux dire clairement plutôt que sous-entendre : aucune sanction n''a pu être documentée pour la seule émission tardive d''une facture électronique ordinaire, par opposition à son absence d''émission. Les articles de sanction sont rédigés autour de la livraison de biens sans facture électronique. Cette page n''affirme pas qu''une sanction pour émission tardive existe, faute d''avoir pu le démontrer.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔗 Connexe, mais délibérément non présenté comme un jalon de facturation électronique', NULL, NULL, 'À compter du 23 août 2026, les fournisseurs non résidents de services électroniques à des consommateurs azerbaïdjanais devront s''immatriculer à la TVA et facturer 18 % dès lors que leurs ventes brutes annuelles de source azerbaïdjanaise dépassent l''équivalent en manats de 10 000 USD, en remplacement d''un dispositif d''immatriculation volontaire et de retenue à la source. Il s''agit d''une obligation d''immatriculation à la TVA et non d''une obligation de facturation électronique — les non-résidents n''émettent pas du tout de factures électroniques azerbaïdjanaises —, de sorte que ce suivi ne l''enregistre pas comme un jalon de mandat. Elle mérite d''être connue pour une seconde raison : une alerte de cabinet de conseil d''avril 2025 annonçait ce changement pour le 1er janvier 2026 et sans seuil, en relevant que la loi habilitante n''avait pas été adoptée. La loi effectivement votée a repoussé la date à août 2026 et ajouté le seuil de 10 000 USD. Un rappel utile de la raison pour laquelle ce site vérifie ce qui a été promulgué plutôt que ce qui était attendu. Par ailleurs, depuis le 1er janvier 2026, un nouvel article 155.1-1 applique un coefficient de 0,5 aux encaissements par carte au point de vente lors du test du seuil d''immatriculation à la TVA : le chiffre d''affaires par carte ne compte donc que pour moitié, ce qui signifie qu''une entreprise peut réaliser environ 400 000 AZN de ventes par carte avant de franchir la barre des 200 000 AZN.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'AZ' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Biens livrés sans facture électronique alors qu''elle était requise — 1re infraction dans l''année civile (art. 58.13)', '10 % de la valeur de la vente, plus 100 AZN par opération non documentée', 'Aucun plafond publié' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Même manquement — 2e infraction au cours de la même année civile (art. 58.13)', '20 % de la valeur de la vente, plus 100 AZN par opération non documentée', 'Aucun plafond publié' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Même manquement — 3e infraction et suivantes (art. 58.13)', '40 % de la valeur de la vente, plus 100 AZN par opération non documentée', 'Aucun plafond publié' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'L''acheteur détient des marchandises sans les factures électroniques ou justificatifs d''achat requis (art. 58.8.2)', '10 % / 20 % / 40 % de la valeur des marchandises, avec aggravation en cas de récidive au cours d''une même année civile', 'Aucun plafond publié' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Produits soumis à accises déplacés entre les propres installations de l''assujetti sans facture électronique de mouvement interne (art. 58.13-1)', '10 % / 20 % / 40 % de la valeur des biens, plus 100 AZN par opération non documentée', 'Aucun plafond publié' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.code = 'AZ' AND pr.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Revoyez votre cycle de facturation pour les services continus', 'C''est le point le plus urgent de cette page. Depuis le 1er janvier 2026, les services fournis de manière régulière et continue — sécurité, nettoyage, services publics, abonnements et la plupart des offres SaaS — doivent être facturés mensuellement, au début de la prestation de chaque mois, même si votre contrat prévoit une facturation trimestrielle ou annuelle. Si votre ERP applique encore une règle générale de cinq jours pour les services, il applique une règle qui n''a plus cours.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Faites passer la facturation du transport avant le transport', 'Les services de transport international doivent désormais être facturés au plus tard au début du transport, et non dans les cinq jours qui suivent. Pour les transporteurs et les logisticiens, cela inverse l''ordre habituel des opérations et exige un changement de processus, pas seulement une modification de champ de date.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Procurez-vous une signature électronique avancée et un compte sur le portail', 'Il vous faut ASAN İMZA, un certificat e-İmza ou un SİMA Token, ainsi qu''un accès au portail İnternet Vergi İdarəsi. Si vous comptez préparer des factures en masse hors ligne, installez également eFP — mais rappelez-vous qu''il prépare les factures sans les émettre.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Surveillez vos factures entrantes, pas seulement vos factures sortantes', 'L''article 58.8.2 sanctionne l''acheteur qui détient des marchandises sans les factures requises, aux mêmes taux progressifs de 10/20/40 %. Relancez les fournisseurs qui n''ont pas émis leur facture et utilisez activement la fenêtre de confirmation de cinq jours — le silence vaut confirmation, si bien qu''une facture non examinée devient une facture acceptée.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Réexaminez votre situation au regard de l''immatriculation à la TVA pour 2026', 'Le nouvel article 155.1-1 ne retient les encaissements par carte au point de vente que pour la moitié de leur valeur lors du test du seuil d''immatriculation de 200 000 AZN : un commerce de détail ou une entreprise de services peut donc désormais réaliser environ 400 000 AZN de chiffre d''affaires par carte avant que l''immatriculation ne devienne obligatoire. Si vous étiez proche de la limite, vous ne l''êtes peut-être plus.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'AZ' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'Service national des impôts — la page officielle consacrée à l''e-qaimə' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'AZ' AND p.url = 'https://www.taxes.gov.az/en/page/elektron-qaime-faktura';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'İnternet Vergi İdarəsi (compte fiscal en ligne) — là où les factures sont réellement émises (connexion requise)' FROM deep_dive_portals p JOIN countries c ON p.country_id = c.id WHERE c.code = 'AZ' AND p.url = 'https://www.e-taxes.gov.az';

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-e-qaime-2017', 'fr',
  'Le mandat e-qaimə débute : assujettis immatriculés à la TVA et personnes relevant de l''article 218.1.2',
  'La décision du Cabinet des ministres n° 89 du 14 mars 2017 a approuvé les règles relatives à la forme, à l''application, à la comptabilisation et à l''utilisation de la facture électronique, mettant en œuvre le nouvel article 71-1 du Code fiscal. À compter du 1er avril 2017, les personnes immatriculées à la TVA et les personnes relevant de l''article 218.1.2 du Code fiscal -- entreprises de commerce et de restauration collective dont les opérations imposables dépassaient 200 000 AZN au cours d''un mois quelconque d''une période glissante de 12 mois -- ont dû émettre des factures électroniques pour les biens livrés, les travaux réalisés et les services rendus dans le cadre de leur activité. Cette date d''entrée en vigueur et ce périmètre sont confirmés sur la page e-qaimə du Service national des impôts lui-même.',
  '["C''est l''origine de l''obligation actuelle -- l''article 71-1 demeure aujourd''hui encore la base juridique applicable", "Note pour qui lirait des commentaires plus anciens : les affirmations selon lesquelles l''Azerbaïdjan aurait rendu la facturation électronique obligatoire en 2010 en vertu de l''article 2 du Code fiscal sont inexactes"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-universal-2018', 'fr',
  'La facturation électronique s''étend à tous les autres assujettis',
  'À compter du 1er janvier 2018, la deuxième phase du même cadre issu de l''article 71-1 a intégré tous les autres assujettis, au-delà des personnes immatriculées à la TVA et de celles relevant de l''article 218.1.2 couvertes depuis avril 2017. À partir de ce moment, le mandat azerbaïdjanais couvre pratiquement l''ensemble des livraisons commerciales B2B, sans aucun seuil de chiffre d''affaires attaché à l''obligation de facturation électronique elle-même. Le phasage est exposé dans la présentation e-qaimə du Service national des impôts lui-même. Les personnes qui ne sont pas immatriculées en tant qu''assujetties ne peuvent pas du tout émettre de factures électroniques.',
  '["Tout assujetti immatriculé qui fournit des biens, des travaux ou des services en Azerbaïdjan entre dans le périmètre -- il n''existe aucun seuil de taille permettant d''en sortir", "Le chiffre de 200 000 AZN que l''on rencontre dans les commentaires azerbaïdjanais sur la facturation électronique correspond à un seuil de délimitation de la phase 2017 et, séparément, à un seuil d''immatriculation à la TVA ; ce n''est pas aujourd''hui un seuil de facturation électronique"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-single-document-2020', 'fr',
  'La facture électronique de TVA est supprimée ; l''e-qaimə devient le document principal unique',
  'À compter du 1er janvier 2020, la facture fiscale électronique (elektron vergi hesab-fakturası, e-VHF) a été supprimée et fusionnée dans l''e-qaimə, devenue le document comptable principal de toutes les opérations commerciales. Les redevables de la TVA utilisent désormais l''e-qaimə elle-même comme document pour calculer et déduire la TVA en amont -- auparavant, elle ne faisait qu''attester le mouvement des marchandises. À compter de la même date, un émetteur ne peut plus annuler unilatéralement une facture sans l''accord du destinataire, et neuf types de factures distincts ont été introduits. Cela mérite d''être dit clairement, car c''est souvent mal décrit : il ne s''agissait pas d''un passage du papier au numérique. Le document azerbaïdjanais antérieur était déjà électronique depuis 2008 environ ; 2020 a fusionné deux systèmes électroniques en un seul.',
  '["Si vos systèmes modélisent encore les factures de TVA et les bons de livraison comme deux documents azerbaïdjanais distincts, ils modélisent un régime qui a pris fin en 2020", "L''annulation requiert désormais l''accord de la contrepartie -- intégrez-le à votre processus d''avoirs et de corrections"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-advance-invoice-2024', 'fr',
  'Les factures électroniques d''acompte deviennent obligatoires',
  'Depuis le 1er janvier 2024, une facture électronique doit être émise le jour même de la réception d''un acompte, et la facture de livraison ultérieure doit renvoyer à cette facture d''acompte par sa série et son numéro. Fait notable, l''obligation ne se limite pas aux redevables de la TVA -- les assujettis au régime simplifié, les non-redevables de la TVA et les redevables de l''impôt sur les bénéfices sont également visés. Fait inhabituel, le dépôt tardif d''une facture électronique d''acompte n''entraîne précisément aucune sanction financière, contrairement aux factures électroniques ordinaires. Des portails fiscaux azerbaïdjanais secondaires citent cette disposition comme l''article 71-1.5.12, tandis que la FAQ 2026 du Service national des impôts lui-même cite la règle de l''acompte comme l''article 71-1.1.5 ; cette divergence de numérotation n''a pas pu être tranchée par rapport à un texte consolidé du Code fiscal et elle est signalée ici plutôt que résolue.',
  '["Déclenchez la facture à la réception de l''acompte, et non à la livraison", "Reportez la série et le numéro de la facture d''acompte sur la facture de livraison", "Ne présumez pas que le critère est l''immatriculation à la TVA -- cette obligation vise aussi les assujettis au régime simplifié et les non-redevables de la TVA"]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'az-timing-rules-2026', 'fr',
  'La fenêtre de cinq jours pour les services se ferme pour le transport international et les services continus',
  'Une loi du 9 décembre 2025, appliquée par le décret présidentiel n° 563 du 29 décembre 2025, a inséré dans le Code fiscal les articles 71-1.1.3-1 et 71-1.1.3-2, avec effet au 1er janvier 2026. Le délai général de cinq jours applicable aux factures de services ne vaut plus pour deux catégories. Les services de transport international doivent être facturés au plus tard au début du transport. Les services fournis de manière régulière et continue -- sécurité, nettoyage, services publics, abonnements -- doivent être facturés pour chaque mois civil au moment où débute la prestation de ce mois, même lorsque le contrat prévoit une facturation trimestrielle ou annuelle. La justification avancée est d''empêcher les contribuables d''utiliser la fenêtre de cinq jours pour déplacer des opérations d''une période déclarative à l''autre.',
  '["Si vous facturez des clients azerbaïdjanais trimestriellement ou annuellement pour un service continu, votre cycle de facturation n''est plus en phase avec la loi -- la facture électronique est mensuelle, quel que soit le cycle de facturation", "Transport international : la facture doit exister avant le début du transport, et non dans les cinq jours qui suivent", "Notez qu''un résumé sectoriel très cité décrit encore une règle générale de cinq jours ; cela n''est plus exact depuis le début de 2026"]'
);

INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-azerbaijan-invoice-timing', 'fr', 'L''Azerbaïdjan ferme la fenêtre de cinq jours pour les services continus et le transport international', 'L''Azerbaïdjan a fermé sa fenêtre de cinq jours pour la facturation des services dans deux catégories. Depuis le 1er janvier 2026, le transport international doit être facturé avant le début du transport et les services continus doivent être facturés mensuellement, quel que soit le cycle de facturation contractuel. Plusieurs synthèses internationales de conformité décrivent encore la règle générale de cinq jours désormais caduque.', '<h3>🇦🇿 L''Azerbaïdjan ferme la fenêtre de cinq jours pour les services continus et le transport international</h3>
<p>Une loi du 9 décembre 2025, appliquée par le décret présidentiel n° 563 du 29 décembre 2025, a inséré deux nouveaux articles dans le Code fiscal azerbaïdjanais, avec effet au 1er janvier 2026. Ensemble, ils mettent fin au délai général de cinq jours qui régissait la facturation des services sous le régime de l''e-qaimə.</p>
<p>Les services de transport international doivent désormais être facturés au plus tard au début du transport — ce qui inverse l''ordre habituel des opérations pour les transporteurs et les logisticiens, habitués à facturer après coup. Les services fournis de manière régulière et continue doivent être facturés pour chaque mois civil au moment où débute la prestation de ce mois, même lorsque le contrat prévoit une facturation trimestrielle ou annuelle. Les orientations du Service national des impôts lui-même prennent pour exemple chiffré un contrat de services de sécurité ; la même logique s''applique au nettoyage, aux services publics, aux abonnements et à la plupart des formules de logiciel en tant que service.</p>
<p>La justification avancée relève d''une lutte anti-abus toute simple : les contribuables utilisaient le délai de grâce de cinq jours pour faire glisser des opérations de part et d''autre des bornes des périodes déclaratives.</p>
<p>Ce qui rend la chose digne d''intérêt, c''est la discrétion avec laquelle elle est passée. Le mandat azerbaïdjanais est universel depuis 2018 et bien établi, si bien qu''il suscite peu de couverture internationale — et au moins une synthèse de conformité très citée énonce encore une règle générale de cinq jours comme si rien n''avait changé. Toute entreprise qui facture un client azerbaïdjanais selon un cycle trimestriel ou annuel pour un service continu a désormais une cadence de facturation en décalage avec la loi, quoi qu''en dise son contrat.</p>');
